mapper.select:
select serial_id, rule_id, cycle_key, current_value, create_time, update_time
from sys_number_serial with (updlock, holdlock)
where rule_id = #{ruleId} and cycle_key = #{cycleKey}

mapper.insert:
insert into sys_number_serial (
    rule_id, cycle_key, current_value, create_time, update_time
) values (
    #{ruleId}, #{cycleKey}, #{currentValue}, getdate(), getdate()
)

mapper.update:
update sys_number_serial
current_value = #{currentValue}, update_time = getdate()
where serial_id = #{serialId}
